/* Audit → Usage. The panel widens for it; figures across the top, then the model split, one bar per pipeline and the
   open pipeline's steps. Neutral ink steps only: models are told apart by name and a grey ramp, never by hue. */
.audit[data-wide] { width: min(880px, calc(100vw - 2 * var(--edge))); }

.usage { display: grid; gap: 20px; padding: 6px 30px 22px; overflow-y: auto; align-content: start; min-height: 0; }
.usage-empty { padding: 18px 30px; }
.usage-note { font-size: var(--t-micro); line-height: 1.5; color: var(--ink-3); max-width: 90ch; }
.u-sub { font-size: var(--t-micro); color: var(--ink-3); }
.u-r { text-align: right; justify-self: end; }
.u-num { font-variant-numeric: tabular-nums; }
.u-dim { color: var(--ink-3); font-variant-numeric: tabular-nums; }

/* figures */
.u-figures { display: grid; grid-template-columns: 1.5fr 1fr 1fr; gap: 28px; }
.u-fig { display: grid; gap: 6px; align-content: start; }
.u-fig .num { font-size: 30px; color: var(--ink); }
.u-budget { position: relative; height: 4px; border-radius: 2px; background: var(--hair); margin-top: 4px; }
.u-budget i { position: absolute; inset: 0 auto 0 0; border-radius: 2px; background: var(--ink); }
.u-budget span { position: absolute; top: -4px; bottom: -4px; width: 1px; background: var(--ink-3); }

/* spend by model: one stacked bar, grey ramp */
.u-models { display: grid; gap: 10px; }
.u-stack { display: flex; height: 8px; border-radius: 4px; overflow: hidden; gap: 2px; }
.u-stack i, .u-legend i { background: var(--ink-3); }
.u-stack i[data-i="0"], .u-legend i[data-i="0"] { background: var(--ink); }
.u-stack i[data-i="1"], .u-legend i[data-i="1"] { background: var(--ink-2); }
.u-legend { display: flex; flex-wrap: wrap; gap: 8px 26px; font-size: var(--t-label); color: var(--ink-2); }
.u-legend span { display: inline-flex; align-items: baseline; gap: 7px; }
.u-legend i { width: 8px; height: 8px; border-radius: 2px; align-self: center; }
.u-legend em { font-style: normal; font-size: var(--t-micro); color: var(--ink-3); }
.u-legend b { font-weight: 500; color: var(--ink); font-variant-numeric: tabular-nums; }

/* pipelines: four selectable bars */
.u-pipes { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.u-pipe { display: grid; gap: 6px; text-align: left; padding: 9px 12px 10px; border-radius: 8px; border: 1px solid var(--hair); transition: border-color var(--fast), background var(--fast); }
.u-pipe:hover { border-color: var(--hair-2); }
.u-pipe[aria-selected="true"] { border-color: var(--hair-2); background: rgba(255, 255, 255, 0.05); }
.u-pipe-top { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
.u-pipe-name { font-size: var(--t-label); font-weight: 600; color: var(--ink); }
.u-pipe-usd { font-size: 15px; color: var(--ink); font-variant-numeric: tabular-nums; }
.u-pipe-bar { height: 2px; border-radius: 1px; background: var(--hair); overflow: hidden; }
.u-pipe-bar i { display: block; height: 100%; background: var(--ink-2); }
.u-pipe[aria-selected="true"] .u-pipe-bar i { background: var(--sweep-hi); }
